 "content": "def transform(grid):
    """Recolor complete, monochromatic separator lines to 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            lines.append(("row", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            lines.append(("col", c, vals[0]))
    for kind, i, color in lines:
        if kind == "row":
            out[i] = [2 if x == color else x for x in out[i]]
        else:
            for r in range(h):
                out[r][i] = 2
    return out
